cat << 'EOF' > /app/submission/boundary_guard.py
import sys, json

for line in sys.stdin:
    if not line.strip(): continue
    try:
        d = json.loads(line)
        req = d.get("request") or {}
        reasons = []

        srcs = {x["id"]: x for x in d.get("sources", [])}
        mems = {x["id"]: x for x in d.get("memories", [])}
        regs = [x for x in d.get("registry", []) if x.get("plugin_id") == req.get("plugin_id") and x.get("status") == "active"]
        creds = {x["id"]: x for x in d.get("credentials", [])}
        apps = {x["id"]: x for x in d.get("approvals", [])}

        if len(regs) != 1:
            reasons.append("invalid registry")
            print(json.dumps({"decision": "deny", "reasons": reasons}))
            continue

        reg = regs[0]
        if reg.get("catalog_trust") != "signed" or not reg.get("catalog_signature_valid"):
            reasons.append("registry not signed")
        if req.get("capability") != reg.get("capability"):
            reasons.append("capability mismatch")

        c = creds.get(req.get("credential_id"))
        if not c or c.get("status") != "active":
            reasons.append("invalid credential")
        elif req.get("plugin_id") not in c.get("plugin_ids", []):
            reasons.append("credential not bound")
        elif not set(reg.get("required_scopes", [])).issubset(set(c.get("scopes", []))):
            reasons.append("missing scopes")

        dests = req.get("destinations", [])
        if not dests or dests[0] != req.get("target"):
            reasons.append("invalid target")
        for dest in dests:
            matched = False
            for a in reg.get("allowed_hosts", []):
                if a.startswith("*.") and dest.endswith(a[1:]) and len(dest) > len(a[1:]):
                    matched = True
                elif dest == a:
                    matched = True
            if not matched:
                reasons.append("unauthorized destination")

        def check_m(mid, vis):
            if mid in vis: return False
            vis.add(mid)
            m = mems.get(mid)
            if not m or m.get("status") != "active": return False
            for sid in m.get("source_ids", []):
                s = srcs.get(sid)
                if not s or s.get("status") != "active": return False
                if reg.get("risk") == "high":
                    if s.get("trust") != "signed" or not s.get("signature_valid"): return False
            for pmid in m.get("parent_memory_ids", []):
                if not check_m(pmid, set(vis)): return False
            return True

        for mid in req.get("memory_ids", []):
            if not check_m(mid, set()):
                reasons.append("invalid memory lineage")

        if reg.get("risk") == "high":
            app = apps.get(req.get("approval_id"))
            if not app or app.get("status") != "active":
                reasons.append("invalid approval")
            elif app.get("type") != "change_ticket":
                reasons.append("wrong approval type")
            elif app.get("plugin_id") != req.get("plugin_id"):
                reasons.append("approval plugin mismatch")
            elif app.get("capability") != req.get("capability"):
                reasons.append("approval cap mismatch")
            elif app.get("target") != req.get("target"):
                reasons.append("approval target mismatch")
            elif app.get("args_digest") != req.get("args_digest"):
                reasons.append("approval args mismatch")

        if req.get("forwards_credential"):
            reasons.append("credential forwarded")

        print(json.dumps({"decision": "allow" if not reasons else "deny", "reasons": reasons}))
    except Exception as e:
        print(json.dumps({"decision": "deny", "reasons": [str(e)]}))
EOF

